1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// 升级测试使用的时间线：
13	//
14	//	t0 12:00 创建活动；窗口 12:00–13:00（[start,end)）；截止 14:00。
15	var upBase = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
16	
17	func upSpec() CampaignSpec {
18		return CampaignSpec{
19			ID:            "cmp-1",
20			Operator:      "alice",
21			CreatedAt:     upBase,
22			TargetVersion: "v2",
23			Devices:       nil,
24			BatchSize:     2,
25			WindowStart:   upBase,
26			WindowEnd:     upBase.Add(time.Hour),
27			Deadline:      upBase.Add(2 * time.Hour),
28		}
29	}
30	
31	// setupUpgrade 登记目标版本 v2（允许 v1）并登记若干 v1 设备。
32	func setupUpgrade(t *testing.T, devices ...string) *Store {
33		t.Helper()
34		s, _ := openTemp(t)
35		if err := s.RegisterUpgrade("v2", []string{"v1"}); err != nil {
36			t.Fatalf("RegisterUpgrade: %v", err)
37		}
38		for _, id := range devices {
39			mustRegister(t, s, id, "v1")
40		}
41		return s
42	}
43	
44	// bringOnline 用一次更大序号的上报把设备置为在线（版本 v1）。
45	func bringOnline(t *testing.T, s *Store, id string) {
46		t.Helper()
47		v, err := s.Get(id)
48		if err != nil {
49			t.Fatalf("Get %s: %v", id, err)
50		}
51		at := upBase.Add(time.Duration(v.LastSeq) * time.Minute).Add(-time.Minute)
52		if err := s.Report(id, v.LastSeq+1, at, "v1", json.RawMessage(`{}`)); err != nil {
53			t.Fatalf("Report %s: %v", id, err)
54		}
55	}
56	
57	func createCampaign(t *testing.T, s *Store, spec CampaignSpec) {
58		t.Helper()
59		if err := s.CreateCampaign(spec); err != nil {
60			t.Fatalf("CreateCampaign: %v", err)
61		}
62	}
63	
64	// finishDevice 完成一台设备的下载与安装，附带版本为 target 的上报（seq 2）。
65	func finishDevice(t *testing.T, s *Store, spec CampaignSpec, id string, at time.Time) {
66		t.Helper()
67		dl, err := s.Claim(spec.ID, id, at)
68		if err != nil {
69			t.Fatalf("claim download %s: %v", id, err)
70		}
71		if dl == nil || dl.Kind != StageDownload {
72			t.Fatalf("want download op for %s, got %+v", id, dl)
73		}
74		if err := s.SubmitResult(OperationResult{
75			CampaignID: spec.ID, DeviceID: id, OperationID: dl.ID, At: at.Add(time.Minute), Success: true,
76		}); err != nil {
77			t.Fatalf("download result %s: %v", id, err)
78		}
79		in, err := s.Claim(spec.ID, id, at.Add(2*time.Minute))
80		if err != nil {
81			t.Fatalf("claim install %s: %v", id, err)
82		}
83		if in == nil || in.Kind != StageInstall {
84			t.Fatalf("want install op for %s, got %+v", id, in)
85		}
86		if err := s.SubmitResult(OperationResult{
87			CampaignID: spec.ID, DeviceID: id, OperationID: in.ID, At: at.Add(3 * time.Minute),
88			Success: true, Seq: 2, Version: "v2", Config: json.RawMessage(`{"ok":true}`),
89		}); err != nil {
90			t.Fatalf("install result %s: %v", id, err)
91		}
92	}
93	
94	func TestRegisterUpgradeValidation(t *testing.T) {
95		s, _ := openTemp(t)
96		cases := []struct {
