1070			!rawEqual(after.Reported, json.RawMessage(`{"a":1}`)) {
1071			t.Fatalf("shadow rewritten by rollback timeout: %+v", after)
1072		}
1073		// 安装失败原因与时间保留，回滚结果未被接受。
1074		if d.InstallFailReason != "install boom" || d.RollbackResult {
