1079	// 迟到提交不校验内容：附带上报缺失、版本不符、配置非法、序号冲突，
1080	// 以及失败结果缺少原因，都不能挡住已领取操作的截止处理。
1081	func TestLateResultAtDeadlineSkipsContentValidation(t *testing.T) {
