3	import (
4		"encoding/json"
5		"testing"
6		"time"
7	)
8	
9	// setCampaignConclusion 直接改写存储文件中活动的整体状态与结束标记，
10	// 用来构造“活动结论与设备进度矛盾”的损坏数据。
11	func setCampaignConclusion(t *testing.T, dir, id, status string, ended bool, endedAt string) []byte {
12		t.Helper()
13		return rewriteStoreBytes(t, dir, func(doc map[string]any) {
14			c := campaignDoc(doc, id)
15			c["status"] = status
16			c["ended"] = ended
17			if endedAt != "" {
18				c["endedAt"] = endedAt
19			} else {
20				delete(c, "endedAt")
21			}
22		})
23	}
24	
25	// TestRestoreCampaignConclusionMustMatchDevices 校验重开存储时活动整体结论
26	// 必须与设备进度一致：仍有设备处于非终态的活动不得写成已结束；全部设备终态后
27	// 活动必须已结束，且只有全部 succeeded 才能 succeeded，其余组合（含回滚成功）
28	// 只能 failed。矛盾时 Open 返回 ErrCorruptStorage，原文件保持不变。
29	func TestRestoreCampaignConclusionMustMatchDevices(t *testing.T) {
30		endedAt := "2026-10-02T13:00:00Z"
31	
32		// 各类“设备尚未终态却把活动写成已结束”的矛盾：
33		// pending、ready（等待安装）、downloading、installing、
34		// awaiting_rollback、rolling_back 都必须让整个存储拒绝打开。
35		t.Run("ended while devices unfinished", func(t *testing.T) {
36			cases := map[string]func(t *testing.T) (dir, campaignID string){
37				"pending": func(t *testing.T) (string, string) {
38					s := setupUpgrade(t, "d1")
39					spec := upSpec()
40					spec.Devices = []string{"d1"}
41					spec.BatchSize = 1
42					createCampaign(t, s, spec)
43					dir := s.dir
44					s.Close()
45					return dir, spec.ID
46				},
47				"ready": func(t *testing.T) (string, string) {
48					_, dir, spec := setupReady(t)
49					return dir, spec.ID
50				},
51				"downloading": func(t *testing.T) (string, string) {
52					s := setupUpgrade(t, "d1")
53					spec := upSpec()
54					spec.Devices = []string{"d1"}
55					spec.BatchSize = 1
56					createCampaign(t, s, spec)
57					bringOnline(t, s, "d1")
58					if _, err := s.Claim(spec.ID, "d1", upBase); err != nil {
59						t.Fatal(err)
60					}
61					dir := s.dir
62					s.Close()
63					return dir, spec.ID
64				},
65				"installing": func(t *testing.T) (string, string) {
66					s := setupUpgrade(t, "d1")
67					spec := upSpec()
68					spec.Devices = []string{"d1"}
69					spec.BatchSize = 1
70					createCampaign(t, s, spec)
71					bringOnline(t, s, "d1")
72					dl, _ := s.Claim(spec.ID, "d1", upBase)
73					if err := s.SubmitResult(OperationResult{
74						CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
75						At: upBase.Add(time.Minute), Success: true,
76					}); err != nil {
77						t.Fatal(err)
78					}
79					if _, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute)); err != nil {
80						t.Fatal(err)
81					}
82					dir := s.dir
83					s.Close()
84					return dir, spec.ID
85				},
86				"awaiting rollback": func(t *testing.T) (string, string) {
87					s, dir, spec, _ := setupInstallFailure(t, true)
88					s.Close()
89					return dir, spec.ID
90				},
91				"rolling back": func(t *testing.T) (string, string) {
92					s, dir, spec, _ := setupInstallFailure(t, true)
93					if _, err := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute)); err != nil {
94						t.Fatal(err)
95					}
96					s.Close()
97					return dir, spec.ID
98				},
99			}
100			for name, build := range cases {
101				t.Run(name, func(t *testing.T) {
102					dir, id := build(t)
103					original := setCampaignConclusion(t, dir, id, CampaignFailed, true, endedAt)
104					assertReopenCorrupt(t, dir, original)
105				})
106			}
107		})
108	
109		// 全部设备安装成功，活动结论却保存为 failed：不能展示错误的升级结果。
110		t.Run("all succeeded saved as failed", func(t *testing.T) {
111			_, dir, spec := setupSucceeded(t)
112			original := setCampaignConclusion(t, dir, spec.ID, CampaignFailed, true, endedAt)
113			assertReopenCorrupt(t, dir, original)
114		})
115	
116		// 存在失败设备，活动却保存为 succeeded。
117		t.Run("failed device but campaign succeeded", func(t *testing.T) {
118			s := setupUpgrade(t, "d1", "d2")
119			spec := upSpec()
120			spec.Devices = []string{"d1", "d2"}
121			spec.BatchSize = 1
122			createCampaign(t, s, spec)
123			bringOnline(t, s, "d1")
124			dl, _ := s.Claim(spec.ID, "d1", upBase)
125			if err := s.SubmitResult(OperationResult{
126				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
127				At: upBase.Add(time.Minute), Success: false, Reason: "boom",
128			}); err != nil {
129				t.Fatal(err)
130			}
131			cv := mustGetCampaign(s, spec.ID)
132			if !cv.Ended || cv.Status != CampaignFailed ||
133				findDevice(cv, "d1").Status != DeviceFailed ||
134				findDevice(cv, "d2").Status != DeviceSkipped {
135				t.Fatalf("precondition: %+v", cv)
136			}
137			dir := s.dir
138			s.Close()
139			original := setCampaignConclusion(t, dir, spec.ID, CampaignSucceeded, true, endedAt)
140			assertReopenCorrupt(t, dir, original)
141		})
142	
143		// 回滚成功只表示恢复到了原版本，不算本次升级成功：活动必须 failed，
144		// 保存成 succeeded 即损坏。
145		t.Run("rollback succeeded but campaign succeeded", func(t *testing.T) {
146			s, dir, spec, rb := setupInstallFailure(t, true)
147			if _, err := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute)); err != nil {
148				t.Fatal(err)
149			}
150			if err := s.SubmitResult(OperationResult{
151				CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
152				At: upBase.Add(5 * time.Minute), Success: true,
153				Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
154			}); err != nil {
155				t.Fatal(err)
156			}
157			cv := mustGetCampaign(s, spec.ID)
158			if !cv.Ended || cv.Status != CampaignFailed ||
159				findDevice(cv, "d1").Status != DeviceRollbackSucceeded {
160				t.Fatalf("precondition: %+v", cv)
161			}
162			s.Close()
163			original := setCampaignConclusion(t, dir, spec.ID, CampaignSucceeded, true, endedAt)
164			assertReopenCorrupt(t, dir, original)
165		})
166	
167		// 全部设备终态（succeeded）后活动却仍标记 running/未结束。
168		t.Run("all terminal but still running", func(t *testing.T) {
169			_, dir, spec := setupSucceeded(t)
170			original := setCampaignConclusion(t, dir, spec.ID, CampaignRunning, false, "")
171			assertReopenCorrupt(t, dir, original)
172		})
173	
174		// 全部设备超时终态、活动却未结束。
175		t.Run("all timeout but still running", func(t *testing.T) {
176			s := setupUpgrade(t, "d1")
177			spec := upSpec()
178			spec.Devices = []string{"d1"}
179			spec.BatchSize = 1
180			createCampaign(t, s, spec)
181			if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
182				t.Fatal(err)
183			}
184			dir := s.dir
185			s.Close()
186			original := setCampaignConclusion(t, dir, spec.ID, CampaignRunning, false, "")
187			assertReopenCorrupt(t, dir, original)
188		})
189	}
