191	// TestRestoreLegitUnfinishedCampaignsReopen 校验尚未完成的正常活动继续保留：
192	// 设备原有待办、批次顺序和操作标识重开后仍可查。
193	func TestRestoreLegitUnfinishedCampaignsReopen(t *testing.T) {
194		// 同批一台设备已经失败（终态），另一台仍未完成时，整体仍在运行：
195		// 正常打开，未失败设备的待办继续可查。
