1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"testing"
7		"time"
8	)
9	
10	// setOpResultAt 直接改写设备某阶段（download/install/rollback）已接受结果的
11	// 首次发生时间（RFC3339 字符串，可用不同时区写法），操作记录与对应的结果
12	// 历史条目一起改写，用来构造按正常流程无法产生的“结果早于首次领取”记录。
13	func setOpResultAt(t *testing.T, dir, campaignID, deviceID, op, at string) []byte {
14		t.Helper()
15		return rewriteStoreBytes(t, dir, func(doc map[string]any) {
16			d := campaignDeviceDoc(doc, campaignID, deviceID)
17			if d == nil {
18				t.Fatalf("device %s missing in campaign %s", deviceID, campaignID)
19			}
20			o := d[op].(map[string]any)
21			opID, _ := o["id"].(string)
22			if opID == "" {
23				t.Fatalf("device %s %s has no operation id", deviceID, op)
24			}
25			o["at"] = at
26			rs := resultDocs(doc, campaignID)
27			var hit bool
28			for _, r := range rs {
29				if r["operationId"] == opID {
30					r["at"] = at
31					hit = true
32				}
33			}
34			if !hit {
35				t.Fatalf("device %s %s result history missing", deviceID, op)
36			}
37		})
38	}
39	
40	// TestRestoreResultBeforeClaimRefused 保护打开存储时的时间顺序核对：对已经
41	// 接受结果的下载、安装、回滚操作，保存的首次结果发生时间不得早于同一活动、
42	// 同一设备、同一阶段的首次领取时间；成功与失败适用同一规则，后来阶段的
43	// 成功或回滚完成不能掩盖早先阶段的矛盾。命中任意一条都必须以 ErrCorruptStorage
44	// 拒绝打开整个存储且原文件内容不变。
45	func TestRestoreResultBeforeClaimRefused(t *testing.T) {
46		// 题设示例：窗口 12:00–13:00，下载 12:10 首次领取，下载结果与历史都记为
47		// 12:05；活动最新时间 12:20、设备已进入等待安装、其他记录自洽，仍须拒绝。
48		t.Run("download result before first claim while ready", func(t *testing.T) {
49			s := setupUpgrade(t, "d1")
50			spec := upSpec()
51			spec.Devices = []string{"d1"}
52			createCampaign(t, s, spec)
53			bringOnline(t, s, "d1")
54			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute))
55			if err := s.SubmitResult(OperationResult{
56				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
57				At: upBase.Add(15 * time.Minute), Success: true,
58			}); err != nil {
59				t.Fatal(err)
60			}
61			// 活动最新时间推进到 12:20，覆盖被改写的 12:05，证明不能靠时间基线放行。
62			if err := s.AdvanceCampaign(spec.ID, upBase.Add(20*time.Minute)); err != nil {
63				t.Fatal(err)
64			}
65			if cv := mustGetCampaign(s, spec.ID); cv.Ended || findDevice(cv, "d1").Status != DeviceReady {
66				t.Fatalf("precondition: %+v", cv)
67			}
68			dir := closeStore(t, s)
69			original := setOpResultAt(t, dir, spec.ID, "d1", "download", "2026-10-02T12:05:00Z")
70			assertReopenCorrupt(t, dir, original)
71		})
72	
73		// 下载失败结果同样适用：失败原因自洽、活动已失败结束也不能掩盖。
74		t.Run("download failure before first claim", func(t *testing.T) {
75			s := setupUpgrade(t, "d1")
76			spec := upSpec()
77			spec.Devices = []string{"d1"}
78			spec.BatchSize = 1
79			createCampaign(t, s, spec)
80			bringOnline(t, s, "d1")
81			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute))
82			if err := s.SubmitResult(OperationResult{
83				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
84				At: upBase.Add(15 * time.Minute), Success: false, Reason: "dl boom",
85			}); err != nil {
86				t.Fatal(err)
87			}
